실행 컨텍스트 내부

ExecutionContext {
  LexicalEnvironment   ← 식별자(변수, 함수) 바인딩 + 외부 스코프 참조
  VariableEnvironment  ← var 선언 전용 (초기에는 LexicalEnvironment와 동일)
  ThisBinding          ← this가 무엇인지
}

LexicalEnvironment {
  EnvironmentRecord   ← 이 컨텍스트에서 선언된 식별자들의 실제 저장소
  outer               ← 바깥 LexicalEnvironment를 가리키는 참조
}

스코프 체인

const x = 1   // 전역

function outer() {
  const y = 2

  function inner() {
    const z = 3
    console.log(x, y, z)  // 1, 2, 3
  }

  inner()
}

──────────────────────────────

inner EC
  EnvironmentRecord: { z: 3 }
  outer: ──────────────────────→ outer EC
                                   EnvironmentRecord: { y: 2, inner: fn }
                                   outer: ─────────────────────────────→ 전역 EC
                                                                           EnvironmentRecord: { x: 1, outer: fn }
                                                                           outer: null

greet('현우')  // '안녕, 현우' — 선언 전에 호출해도 동작함

function greet(name) {
  return `안녕, ${name}`
}

// 함수 선언문 — 어디서든 호출 가능
greet()  // ✅ 동작

function greet() {
  console.log('hello')
}

// 함수 표현식 — 할당 전에 호출 불가
greet()  // ❌ TypeError: greet is not a function

var greet = function() {
  console.log('hello')
}

function makeCounter() {
  let count = 0            // ← makeCounter의 LexicalEnvironment에 존재

  return function increment() {
    count++
    return count
  }
}

const counter = makeCounter()
counter()  // 1
counter()  // 2
counter()  // 3

function makeCounter() {
  let count = 0

  return {
    increment() { count++ },        // ← 같은 LexicalEnvironment 참조
    decrement() { count-- },        // ← 같은 LexicalEnvironment 참조
    getCount()  { return count },   // ← 같은 LexicalEnvironment 참조
  }
}

const counter = makeCounter()
counter.increment()
counter.increment()
counter.decrement()
counter.getCount()  // 1 — 세 함수가 count를 공유함

for (var i = 0; i < 3; i++) {
  setTimeout(function() {
    console.log(i)   // 3, 3, 3 — 0, 1, 2가 아님
  }, 100)
}

for (let i = 0; i < 3; i++) {
  setTimeout(function() {
    console.log(i)   // 0, 1, 2
  }, 100)
}

const x = 'global'

function outer() {
  const y = 'outer'

  function inner() {
    const z = 'inner'
    console.log(x, y, z)
  }

  inner()
}

outer()
